-- LibForeverData @VERSION@ (client @CLIENT@): World of Warcraft: Forever quest data for any addon.
-- Generated by `forge data publish --lua` from the forever-db release. Do not edit.
-- Licences: the database GPL-3.0 (LICENSE.txt), quest steps and notes CC BY 4.0
-- (LICENSE-CC-BY-4.0.txt); credits in NOTICE.md.
--
-- Use it through `## Dependencies: LibForeverData` (or OptionalDeps and a test for the global),
-- or embed the folder; the newest copy loaded wins. Every answer is a fresh table.
--
--   LibForeverData.Get(kind, id) -> record | nil   kind "quest", "npc", "object", "item"
--   LibForeverData.Name(kind, id) -> name | nil     (a quest's title)
--   LibForeverData.Ids(kind) -> { id, ... } sorted
--   LibForeverData.Spawns(kind, id) -> { { map, x, y, z }, ... }   kind "npc" | "object";
--       world yards on the client Map id (continent or instance); z nil when unknown
--   LibForeverData.ToUiMap(map, x, y) -> uiMapID, x%, y% | nil   (the smallest map frame holding it)
--   LibForeverData.Quest(id) -> the quest record: start, finish, objectives, prereqs, rewards
--   LibForeverData.Steps(questId) -> { { n, id, action, targetKind, target, count, place, text,
--       confidence }, ... }   confidence "unconfirmed" for a community note not yet confirmed
--   LibForeverData.Notes(questId) -> { { id, kind, text, place, confidence }, ... }
--   LibForeverData.version, .clientBuild, .api
--
-- Records. quest: id, name (= title), level, minLevel, races, classes (client masks, 0 every),
-- side (0 both, 1 Alliance, 2 Horde), xp, money (copper), type, zone (AreaTable id), repeatable,
-- start / finish { { kind, id } } (kind npc, object, item), objectives { { kind, target, count } },
-- prereqs { { quest, mode = "all" | "any", breadcrumb } }, rewards { { kind = "item" | "choice" |
-- "rep", id, count } }; and LibDingDB's names: questLevel, requiredLevel, requiredRaces,
-- requiredClasses, startedBy / finishedBy { npcs, objects, items }, preQuestGroup, preQuestSingle.
-- npc: id, name, subName, minLevel, maxLevel, factionTemplate, rank (0 normal, 1 elite, 2 rare
-- elite, 3 boss, 4 rare), spawns. object: id, name, type, spawns. item: id, name, questItem,
-- sources { { kind, id, chance } }, npcDrops, objectDrops. `spawns` is LibDingDB's shape:
-- { [uiMapID] = { x1, y1, x2, y2, ... } } in map percent.

local _, ns = ...
ns = ns or {}
local LuaChunks = ns.LuaChunks
local RANK = @RANK@

local current = LibForeverData
if type(current) == "table" and (current._rank or 0) >= RANK then
	-- An equal or newer copy is loaded already: this copy's data files skip.
	return
end

local lib = { version = "@VERSION@", clientBuild = "@CLIENT@", api = @API@, _rank = RANK }
LibForeverData = lib
ns.LibForeverData = lib

local store = LuaChunks.New()
local Split, Unesc, Fixed = LuaChunks.Split, LuaChunks.Unesc, LuaChunks.Fixed
local tonumber, type, pairs, ipairs, sub, find, floor = tonumber, type, pairs, ipairs, string.sub, string.find, math.floor

function lib._Add(kind, lo, hi, text)
	store:Add(kind, lo, hi, text)
end

-- uiMapID, Map id, left, right, top, bottom: world y at the map's left and right edge, world x at
-- its top and bottom.
local FRAMES = {
@FRAMES@}

local function n(s)
	if s == nil or s == "" then return nil end
	return tonumber(s)
end

local KIND = { n = "npc", o = "object", i = "item", k = "kill", e = "event", t = "talk", c = "choice", r = "rep" }

local function copy(v)
	if type(v) ~= "table" then return v end
	local t = {}
	for k, x in pairs(v) do t[k] = copy(x) end
	return t
end

function lib.ToUiMap(map, x, y)
	local best, bx, by, area
	for i = 1, #FRAMES do
		local f = FRAMES[i]
		if f[2] == map then
			local px = (y - f[3]) / (f[4] - f[3]) * 100
			local py = (x - f[5]) / (f[6] - f[5]) * 100
			if px >= 0 and px <= 100 and py >= 0 and py <= 100 then
				local a = math.abs((f[4] - f[3]) * (f[6] - f[5]))
				if not area or a < area then
					best, bx, by, area = f[1], px, py, a
				end
			end
		end
	end
	if best then return best, floor(bx * 100 + 0.5) / 100, floor(by * 100 + 0.5) / 100 end
end

local function points(s)
	local out = {}
	if not s then return out end
	for at = 1, #s - 10, 11 do
		local z = Fixed(s, at + 8, 3)
		out[#out + 1] = {
			Fixed(s, at, 2),
			(Fixed(s, at + 2, 3) - 131072) / 2,
			(Fixed(s, at + 5, 3) - 131072) / 2,
			z ~= 262143 and (z - 131072) / 10 or nil,
		}
	end
	return out
end

local function spawnsKind(kind)
	return kind == "object" and "objectSpawn" or "npcSpawn"
end

-- LibDingDB's spawns: { [uiMapID] = { x1, y1, ... } }
local function uiSpawns(kind, id)
	local out
	for _, p in ipairs(points(store:Raw(spawnsKind(kind), id))) do
		local m, x, y = lib.ToUiMap(p[1], p[2], p[3])
		if m then
			out = out or {}
			local l = out[m] or {}
			out[m] = l
			l[#l + 1] = x
			l[#l + 1] = y
		end
	end
	return out
end

local function ents(s)
	local out = {}
	for _, e in ipairs((Split(s, ","))) do
		if e ~= "" then out[#out + 1] = { kind = KIND[sub(e, 1, 1)], id = n(sub(e, 2)) } end
	end
	return out
end

local function grouped(list)
	local g = {}
	for _, e in ipairs(list) do
		local k = e.kind .. "s"
		g[k] = g[k] or {}
		g[k][#g[k] + 1] = e.id
	end
	return { g.npcs, g.objects, g.items }
end

local DECODE = {}

function DECODE.quest(s, id)
	local f = Split(s, ";")
	local q = {
		id = id, name = Unesc(f[1]), level = n(f[2]), minLevel = n(f[3]), races = n(f[4]) or 0, classes = n(f[5]) or 0,
		side = n(f[6]), xp = n(f[7]), money = n(f[8]), type = n(f[9]), zone = n(f[10]), repeatable = f[11] == "1",
		start = ents(f[12]), finish = ents(f[13]), objectives = {}, prereqs = {}, rewards = {},
	}
	q.title = q.name
	for _, o in ipairs((Split(f[14], ","))) do
		if o ~= "" then
			local p = Split(o, ":")
			q.objectives[#q.objectives + 1] = { kind = KIND[p[1]], target = n(p[2]), count = n(p[3]) }
		end
	end
	local all, any = {}, {}
	for _, o in ipairs((Split(f[15], ","))) do
		if o ~= "" then
			local p = Split(o, ":")
			local pre = { quest = n(p[1]), mode = p[2] == "y" and "any" or "all", breadcrumb = p[3] == "1" }
			q.prereqs[#q.prereqs + 1] = pre
			local l = pre.mode == "any" and any or all
			l[#l + 1] = pre.quest
		end
	end
	for _, o in ipairs((Split(f[16], ","))) do
		if o ~= "" then
			local p = Split(o, ":")
			q.rewards[#q.rewards + 1] = { kind = KIND[p[1]] == "item" and "item" or KIND[p[1]], id = n(p[2]), count = n(p[3]) }
		end
	end
	q.questLevel, q.requiredLevel, q.requiredRaces, q.requiredClasses = q.level, q.minLevel, q.races, q.classes
	q.startedBy, q.finishedBy = grouped(q.start), grouped(q.finish)
	q.preQuestGroup = all[1] and all or nil
	q.preQuestSingle = any[1] and any or nil
	return q
end

function DECODE.npc(s, id)
	local f = Split(s, ";")
	return { id = id, name = Unesc(f[1]), subName = Unesc(f[2]), minLevel = n(f[3]), maxLevel = n(f[4]), factionTemplate = n(f[5]), rank = n(f[6]) }
end

function DECODE.object(s, id)
	local f = Split(s, ";")
	return { id = id, name = Unesc(f[1]), type = n(f[2]) }
end

function DECODE.item(s, id)
	local f = Split(s, ";")
	local it = { id = id, name = Unesc(f[1]), questItem = f[2] == "1", sources = {} }
	local drops = { npc = {}, object = {} }
	for _, e in ipairs((Split(f[3], ","))) do
		if e ~= "" then
			local p = Split(e, ":")
			local src = { kind = KIND[sub(p[1], 1, 1)], id = n(sub(p[1], 2)), chance = n(p[2]) }
			it.sources[#it.sources + 1] = src
			local d = drops[src.kind]
			if d then d[#d + 1] = src.id end
		end
	end
	it.npcDrops = drops.npc[1] and drops.npc or nil
	it.objectDrops = drops.object[1] and drops.object or nil
	return it
end

local function placeOf(s)
	if not s or s == "" then return nil end
	local p = Split(s, ",")
	return { map = n(p[1]), x = n(p[2]), y = n(p[3]) }
end

function DECODE.steps(s)
	local out = {}
	for _, r in ipairs((Split(s, "|"))) do
		local p = Split(r, ":")
		out[#out + 1] = {
			n = n(p[1]), id = Unesc(p[2]), action = Unesc(p[3]), targetKind = Unesc(p[4]), target = n(p[5]), count = n(p[6]),
			place = placeOf(p[7]), text = Unesc(p[8]), confidence = p[9] == "u" and "unconfirmed" or nil,
		}
	end
	return out
end

function DECODE.notes(s)
	local out = {}
	for _, r in ipairs((Split(s, "|"))) do
		local p = Split(r, ":")
		out[#out + 1] = { id = Unesc(p[1]), kind = Unesc(p[2]), place = placeOf(p[3]), text = Unesc(p[4]), confidence = p[5] == "u" and "unconfirmed" or nil }
	end
	return out
end

local KINDS = { quest = true, npc = true, object = true, item = true }

function lib.Get(kind, id)
	if not KINDS[kind] then return nil end
	local rec = store:Get(kind, id, DECODE[kind])
	if not rec then return nil end
	rec = copy(rec)
	if kind == "npc" or kind == "object" then rec.spawns = uiSpawns(kind, rec.id) end
	return rec
end

function lib.Name(kind, id)
	if not KINDS[kind] then return nil end
	local s = store:Raw(kind, id)
	if not s then return nil end
	local e = find(s, ";", 1, true)
	return Unesc(e and sub(s, 1, e - 1) or s)
end

function lib.Ids(kind)
	if not KINDS[kind] then return {} end
	return store:Ids(kind)
end

function lib.Spawns(kind, id)
	local out = {}
	for i, p in ipairs(points(store:Raw(spawnsKind(kind), id))) do
		out[i] = { map = p[1], x = p[2], y = p[3], z = p[4] }
	end
	return out
end

function lib.Quest(id)
	return lib.Get("quest", id)
end

function lib.Steps(questId)
	return copy(store:Get("steps", questId, DECODE.steps)) or {}
end

function lib.Notes(questId)
	return copy(store:Get("notes", questId, DECODE.notes)) or {}
end
